/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

const lerp = (a: number, b: number, k: number) => a + (b - a) * k;

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

const WARP_IN = [-6, 22] as const;
const WEAVE_START = 22;
const PAD = { value: [3, 2], mark: [2, 1] } as const;

function ThreadWeaveBase({
  value = "24",
  motif = "value",
  caption = "frames per second",
  accent = "#3B5BFD",
  ink,
  background,
  fontFamily = sans,
  weave = WEAVE_BUDGET,
  stats = true,
  logo,
  grain = true,
  scale: zoom = 1,
  delay: wait = 0,
  speed = 1,
  theme = "dark",
}: ThreadWeaveProps) {
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - wait) * speed;
  const { width, height } = useSceneConfig();
  const u = height / 720;
  const p = THEMES[theme];
  const fg = ink ?? p.fg;
  const stage =
    background === "transparent" ? "transparent" : (background ?? p.bg);

  const bitmap = motifBitmap(value, motif);
  const [PAD_X, PAD_Y] = PAD[motif];
  const bw = Math.max(...bitmap.map((r) => r.length), 1);
  const bh = bitmap.length;
  const pxW = bw + PAD_X * 2;
  const pxH = bh + PAD_Y * 2;
  const cols = pxW * 2;
  const rows = pxH * 2;

  const sy = Math.min((height * 0.6) / rows, (width * 0.7) / (cols * 0.94));
  const sx = sy * 0.94;
  const clothW = cols * sx;
  const clothH = rows * sy;
  const footer = 46 * u;
  const left = (width - clothW) / 2;
  const top = (height - clothH - footer) / 2;
  const fringe = 0.9 * sy;
  const barH = sy * 0.86;
  const warpW = sx * 0.3;

  const colorAt = (r: number, c: number) => {
    const py = Math.floor(r / 2) - PAD_Y;
    const px = Math.floor(c / 2) - PAD_X;
    const ch = bitmap[py]?.[px];
    if (ch !== "1") return p.weft;
    const gx = px / Math.max(1, bw - 1);
    const gy = py / Math.max(1, bh - 1);
    return figureColor(theme, accent, 0.55 * gx + 0.45 * (1 - gy));
  };

  const durs: number[] = [];
  const starts: number[] = [];
  const raw = Array.from({ length: rows }, (_, r) =>
    lerp(6.6, 3.4, EASE_OUT(r / Math.max(1, rows - 1))),
  );
  const fit = Math.min(1, weave / raw.reduce((a, b) => a + b, 0));
  let acc = WEAVE_START;
  for (let r = 0; r < rows; r++) {
    const d = raw[r] * fit;
    starts.push(acc);
    durs.push(d);
    acc += d;
  }
  const weaveEnd = acc;
  const beatLen = 7;

  const rowState = (r: number) => {
    const s = starts[r];
    const e = s + durs[r];
    const prog = interpolate(t, [s, e], [0, 1], { ...CLAMP, easing: EASE_IO });
    const beat = interpolate(t, [e, e + beatLen], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    const y = top + (r + 0.5) * sy - (1 - beat) * 0.32 * sy;
    const ltr = r % 2 === 0;
    return { prog, y, ltr, started: t >= s };
  };

  const states = Array.from({ length: rows }, (_, r) => rowState(r));
  const picks = states.filter((s) => s.prog >= 1).length;

  const settle = interpolate(t, [weaveEnd, weaveEnd + 16], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const footA = interpolate(t, [10, 26], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const capA = interpolate(t, [weaveEnd + 2, weaveEnd + 18], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const warpEls = Array.from({ length: cols }, (_, c) => {
    const x = left + (c + 0.5) * sx;
    const mid = (cols - 1) / 2;
    const delay = (Math.abs(c - mid) / Math.max(1, mid)) * 10;
    const g = interpolate(
      t,
      [WARP_IN[0] + delay, WARP_IN[1] - 10 + delay],
      [0, 1],
      {
        ...CLAMP,
        easing: EASE_OUT,
      },
    );
    const y0 = top - fringe;
    const y1 = top + clothH + fringe;
    return (
      <rect
        key={`w${x}`}
        x={x - warpW / 2}
        y={y0}
        width={warpW}
        height={(y1 - y0) * g}
        rx={warpW / 2}
        fill={p.warp}
      />
    );
  });

  const weftEls: React.ReactNode[] = [];
  const tickEls: React.ReactNode[] = [];
  const loopEls: React.ReactNode[] = [];
  const xL = left;
  const xR = left + clothW;
  const capR = barH / 2;

  for (let r = 0; r < rows; r++) {
    const st = states[r];
    if (!st.started) continue;
    const reach = st.prog;
    const tip = st.ltr ? lerp(xL, xR, reach) : lerp(xR, xL, reach);
    const visLo = st.ltr ? xL : tip;
    const visHi = st.ltr ? tip : xR;
    for (let c = 0; c < cols; c++) {
      const cx0 = left + c * sx;
      const cx1 = cx0 + sx;
      const lo = Math.max(cx0, visLo);
      const hi = Math.min(cx1, visHi);
      if (hi <= lo) continue;
      weftEls.push(
        <rect
          key={`f${r}-${c}`}
          x={lo - 0.4}
          y={st.y - barH / 2}
          width={hi - lo + 0.8}
          height={barH}
          fill={colorAt(r, c)}
        />,
      );
      const wx = cx0 + sx / 2;
      const passed = st.ltr ? tip >= wx + warpW : tip <= wx - warpW;
      if ((r + c) % 2 === 1 && passed) {
        tickEls.push(
          <g key={`t${r}-${c}`}>
            <rect
              x={wx - warpW / 2 - 1.6 * u}
              y={st.y - barH / 2}
              width={warpW + 3.2 * u}
              height={barH}
              fill={p.shade}
            />
            <rect
              x={wx - warpW / 2}
              y={st.y - barH / 2 - 0.5}
              width={warpW}
              height={barH + 1}
              fill={p.warp}
            />
          </g>,
        );
      }
    }
    const lead = st.prog > 0 && st.prog < 1 ? tip : null;
    if (lead !== null) {
      weftEls.push(
        <circle
          key={`h${r}`}
          cx={lead}
          cy={st.y}
          r={capR}
          fill={colorAt(
            r,
            Math.max(0, Math.min(cols - 1, Math.floor((lead - left) / sx))),
          )}
        />,
      );
    }
    if (r === 0 && st.prog > 0) {
      weftEls.push(
        <circle key="cap0" cx={xL} cy={st.y} r={capR} fill={p.weft} />,
      );
    }
    if (r === rows - 1 && st.prog >= 1) {
      weftEls.push(
        <circle
          key="cap1"
          cx={st.ltr ? xR : xL}
          cy={st.y}
          r={capR}
          fill={p.weft}
        />,
      );
    }
    if (r > 0) {
      const prev = states[r - 1];
      const side = prev.ltr ? xR : xL;
      const dir = prev.ltr ? 1 : -1;
      const k = interpolate(st.prog, [0, 0.12], [0, 1], CLAMP);
      if (k > 0) {
        const rr = (st.y - prev.y) / 2;
        const rx = sy * 0.3;
        const cyM = (st.y + prev.y) / 2;
        const ang = Math.PI * k;
        const ex = side + dir * Math.sin(ang) * rx;
        const ey = cyM - Math.cos(ang) * rr;
        loopEls.push(
          <path
            key={`l${r}`}
            d={`M${side} ${prev.y} A${rx} ${rr} 0 0 ${dir > 0 ? 1 : 0} ${ex} ${ey}`}
            fill="none"
            stroke={p.weft}
            strokeWidth={barH * 0.9}
          />,
        );
      }
    }
  }

  const scaleAt = (f: number) =>
    lerp(1.025, 1, EASE_IO(Math.max(0, Math.min(1, f / (weaveEnd + 16)))));
  const scale = scaleAt(t);
  // Weighed at the frame's corner, the furthest the caption can sit from the
  // camera's origin.
  const reach = Math.hypot(width, height) / 2;
  const cameraMoving =
    Math.abs(scaleAt(t + speed) - scale) * reach > 1e-3 ||
    Math.abs(scale - scaleAt(t - speed)) * reach > 1e-3;

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <ScaleLayer scale={zoom}>
        <AbsoluteFill
          style={{
            transform: `scale(${scale})${glide(cameraMoving)}`,
            transformOrigin: "50% 46%",
          }}
        >
          <svg
            width={width}
            height={height}
            style={{ position: "absolute", inset: 0 }}
            aria-hidden
          >
            {warpEls}
            {loopEls}
            {weftEls}
            {tickEls}
          </svg>
          <div
            style={{
              position: "absolute",
              left,
              top: top + clothH + fringe + 18 * u,
              width: clothW,
              display: "flex",
              justifyContent: "space-between",
              alignItems: "baseline",
              fontFamily,
              whiteSpace: "nowrap",
            }}
          >
            <div
              style={{
                fontSize: 20 * u,
                fontWeight: 500,
                letterSpacing: "-0.015em",
                color: fg,
                opacity: capA,
                transform: `translateY(${(1 - capA) * 8 * u}px)${glide(midway(capA) && !cameraMoving)}`,
              }}
            >
              {caption === "remocn"
                ? (logo ?? <RemocnLogo fontSize={22 * u} color={fg} />)
                : caption}
            </div>
            {stats ? (
              <div
                style={{
                  fontFamily: mono,
                  fontSize: 14 * u,
                  fontWeight: 400,
                  letterSpacing: "0.01em",
                  color: p.muted,
                  fontVariantNumeric: "tabular-nums",
                  opacity: footA * lerp(1, 0.85, settle),
                }}
              >
                {`${cols} ends × ${picks} picks`}
              </div>
            ) : null}
          </div>
        </AbsoluteFill>
      </ScaleLayer>
      {grain ? <Grain opacity={p.grain} /> : null}
    </AbsoluteFill>
  );
}

