const ELEMENT_PROP_KEYS = new Set(["theme","accent","value","caption","motif","weave","stats","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  value: "24",
  caption: "frames per second",
  motif: "value",
  weave: 108,
